def cantor_numbering(N: int) -> str:
    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer.")

    level = 1
    while N > level:
        N -= level
        level += 1

    if level % 2 == 0:
        numerator = N
        denominator = level - N + 1
    else:
        numerator = level - N + 1
        denominator = N

    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N <= 0 or K <= 0 or K >= N:
        raise ValueError("Invalid input: num_str must be a digit string, N must be positive, and K must be positive and less than N.")

    def helper(start, k):
        if k == 0:
            return int(num_str[start:])
        max_prod = 0
        for i in range(start + 1, N - k + 1):
            current_prod = int(num_str[start:i]) * helper(i, k - 1)
            max_prod = max(max_prod, current_prod)
        return max_prod

    return helper(0, K)

