def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        # Remove hyphens to work with the digits only
        digits = [d for d in isbn if d != '-']
        total = 0
        for i in range(9):
            total += (i + 1) * int(digits[i])
        # Calculate checksum
        remainder = total % 11
        checksum = 'X' if remainder == 10 else str(remainder)
        return checksum

    try:
        # Validate format
        if len(isbn) != 13 or isbn[1] != '-' or isbn[5] != '-' or isbn[11] != '-':
            raise ValueError("ISBN format is incorrect")

        # Extract provided checksum
        provided_checksum = isbn[-1]
        # Calculate the correct checksum
        correct_checksum = calculate_checksum(isbn)

        if provided_checksum == correct_checksum:
            return "Right"
        else:
            # Return corrected ISBN with the correct checksum
            return isbn[:-1] + correct_checksum

    except ValueError as ve:
        return str(ve)
    except Exception as e:
        return f"An error occurred: {str(e)}"

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will store the number of ways to reach student i after j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1  # Starting at student 0 with 0 passes

    for passes in range(1, m + 1):
        for student in range(n):
            left_student = (student - 1) % n
            right_student = (student + 1) % n
            dp[student][passes] = dp[left_student][passes - 1] + dp[right_student][passes - 1]

    return dp[0][m]

