def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque, defaultdict

    # Create a transformation map from rules
    transform_map = defaultdict(set)
    for x, y in rules:
        transform_map[x].add(y)

    # BFS setup
    queue = deque([str(n)])
    visited = set([str(n)])

    while queue:
        current_str = queue.popleft()

        # Generate all possible transformations of the current number
        for i, digit in enumerate(current_str):
            if int(digit) in transform_map:
                for new_digit in transform_map[int(digit)]:
                    new_number_str = current_str[:i] + str(new_digit) + current_str[i+1:]
                    if new_number_str not in visited:
                        visited.add(new_number_str)
                        queue.append(new_number_str)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    try:
        # Iterate through each participant and their statements
        for participant, stmts in statements.items():
            for statement in stmts:
                # Skip statements that mention days of the week
                if any(day in statement for day in days_of_week):
                    continue

                # Determine if the participant is a liar or not
                is_liar = participant in liar_count

                # Check statements about the scenario participant's guilt
                if f"{scenario} is guilty." in statement:
                    if is_liar and scenario != participant:
                        continue
                    elif not is_liar and scenario == participant:
                        continue
                    else:
                        return False

                if f"{scenario} is not guilty." in statement:
                    if is_liar and scenario == participant:
                        continue
                    elif not is_liar and scenario != participant:
                        continue
                    else:
                        return False

        return True
    except Exception as e:
        return False

def calculate_score(system: int, points: str) -> list:
    if system not in (11, 21):
        raise ValueError("The scoring system must be either 11 or 21 points.")
    if not all(char in ('W', 'L') for char in points):
        raise ValueError("The points string must only contain 'W' and 'L' characters.")

    scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If the loop ends in the middle of a game, include the current score
    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

