def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l < 0:
        raise ValueError("The length of the road must be non-negative.")
    if not all(0 <= start <= end < l for start, end in areas):
        raise ValueError("All areas must be within the bounds of the road and start must be less than or equal to end.")

    cleared_positions = set()
    for start, end in areas:
        cleared_positions.update(range(start, end + 1))

    return l - len(cleared_positions)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the maximum value that can be obtained with each time limit
    dp = [0] * (T + 1)

    # Iterate over each herb
    for time, value in herbs:
        # Update the dp array from right to left to avoid using the same herb multiple times
        for t in range(T, time - 1, -1):
            dp[t] = max(dp[t], dp[t - time] + value)

    # The maximum value is found at dp[T]
    return dp[T]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # dp[i][j] will store the number of ways to use j pots with the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # There's one way to arrange 0 pots with 0 types of flowers

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters.")

    key = key.lower()
    ciphertext = ciphertext.lower()
    key_length = len(key)
    decrypted_text = []

    for i, char in enumerate(ciphertext):
        key_char = key[i % key_length]
        shift = ord(key_char) - ord('a')
        decrypted_char = chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
        decrypted_text.append(decrypted_char)

    return ''.join(decrypted_text)

def mod_inverse(a, b):
    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return (gcd, x, y)

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0
    threshold = 8

    for i, (school_hours, extra_hours) in enumerate(schedule, start=1):
        total_hours = school_hours + extra_hours
        if total_hours > threshold:
            unhappiness = total_hours - threshold
            if unhappiness > max_unhappiness:
