def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Initialize increasing and decreasing arrays
    increasing = [1] * n
    decreasing = [1] * n

    # Fill increasing array
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            increasing[i] = increasing[i - 1] + 1

    # Fill decreasing array
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            decreasing[i] = decreasing[i + 1] + 1

    # Calculate the minimum students to leave
    min_students = n
    for i in range(n):
        total_students = increasing[i] + decreasing[i] - 1
        students_to_leave = n - total_students
        min_students = min(min_students, students_to_leave)

    return min_students

def min_groups(w, n, prices):
    if not isinstance(w, int) or not isinstance(n, int) or not isinstance(prices, list):
        raise ValueError("Invalid input types")
    if w < 0 or n < 0:
        raise ValueError("w and n must be non-negative")
    if len(prices) != n:
        raise ValueError("The length of prices must match n")
    if any(not isinstance(price, int) or price < 0 for price in prices):
        raise ValueError("All prices must be non-negative integers")

    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("The number of disc pairs must be at least 1.")

    moves = 0
    current_moves = 1

    for _ in range(n):
        current_moves = 3 * current_moves - 1
        moves = current_moves

    return moves

def total_smoked_cigarettes(n, k):
    if n < 0 or k <= 1:
        raise ValueError("Invalid input: n must be non-negative and k must be greater than 1.")

    total_smoked = n
    butts = n

    while butts >= k:
        new_cigarettes = butts // k
        total_smoked += new_cigarettes
        butts = butts % k + new_cigarettes

    return total_smoked
